export interface InputData {
  temperature: number;
  fromUnit: 'Celsius' | 'Fahrenheit' | 'Kelvin';
  toUnit: 'Celsius' | 'Fahrenheit' | 'Kelvin';
}

export interface ConversionResult {
  convertedTemperature: number;
}

export function handleConversion(input: InputData): ConversionResult {
  let convertedTemp = input.temperature;

  if (input.fromUnit === 'Celsius') {
    if (input.toUnit === 'Fahrenheit') {
      convertedTemp = (input.temperature * 9 / 5) + 32;
    } else if (input.toUnit === 'Kelvin') {
      convertedTemp = input.temperature + 273.15;
    }
  } else if (input.fromUnit === 'Fahrenheit') {
    if (input.toUnit === 'Celsius') {
      convertedTemp = (input.temperature - 32) * 5 / 9;
    } else if (input.toUnit === 'Kelvin') {
      convertedTemp = ((input.temperature - 32) * 5 / 9) + 273.15;
    }
  } else if (input.fromUnit === 'Kelvin') {
    if (input.toUnit === 'Celsius') {
      convertedTemp = input.temperature - 273.15;
    } else if (input.toUnit === 'Fahrenheit') {
      convertedTemp = ((input.temperature - 273.15) * 9 / 5) + 32;
    }
  }

  return { convertedTemperature: convertedTemp };
}

export function renderConversionResult(result: ConversionResult): void {
  console.log(`Converted temperature: ${result.convertedTemperature}`);
}

