export function render(container) {
  container.innerHTML = `
    <div class="app">
      <h1>TempConverter</h1>
      <div class="row">
        <input type="number" id="celsiusInput" placeholder="Celsius" />
        <input type="number" id="fahrenheitInput" placeholder="Fahrenheit" />
        <input type="number" id="kelvinInput" placeholder="Kelvin" />
      </div>
      <button class="btn" onclick="convertTemps()">Convert</button>
      <button class="btn" onclick="resetInputs()">Reset</button>
      <div id="results"></div>
    </div>
  `;

  function convertTemps() {
    const celsiusInput = parseFloat(document.getElementById('celsiusInput').value);
    const fahrenheitInput = parseFloat(document.getElementById('fahrenheitInput').value);
    const kelvinInput = parseFloat(document.getElementById('kelvinInput').value);

    if (isNaN(celsiusInput)) {
      document.getElementById('results').textContent = 'Please enter a valid temperature value';
      return;
    }

    const convertedCelsius = ((fahrenheitInput - 32) * 5 / 9).toFixed(2);
    const convertedFahrenheit = ((celsiusInput * 9 / 5) + 32).toFixed(2);
    const convertedKelvin = (celsiusInput + 273.15).toFixed(2);

    document.getElementById('results').textContent = `Celsius: ${convertedCelsius}, Fahrenheit: ${convertedFahrenheit}, Kelvin: ${convertedKelvin}`;
  }

  function resetInputs() {
    document.getElementById('celsiusInput').value = '';
    document.getElementById('fahrenheitInput').value = '';
    document.getElementById('kelvinInput').value = '';
    document.getElementById('results').textContent = '';
  }
}

