export interface ConversionRequest {
  temperature: number;
  fromUnit: 'Celsius' | 'Fahrenheit' | 'Kelvin';
  toUnit: 'Celsius' | 'Fahrenheit' | 'Kelvin';
}

export interface ConversionResult {
  convertedTemperature: number;
}

export function processConversionRequest(request: ConversionRequest): ConversionResult {
  try {
    const result = handleConversion(request);
    return result;
  } catch (error) {
    throw new Error(`Failed to process conversion: ${error.message}`);
  }
}

