export function handleConversion(request: ConversionRequest): ConversionResult {
  const { temperature, fromUnit, toUnit } = request;

  const conversionTable: Record<string, Record<string, (temp: number) => number>> = {
    Celsius: { Fahrenheit: (temp: number) => (temp * 9 / 5) + 32, Kelvin: (temp: number) => temp + 273.15 },
    Fahrenheit: { Celsius: (temp: number) => (temp - 32) * 5 / 9, Kelvin: (temp: number) => ((temp - 32) * 5 / 9) + 273.15 },
    Kelvin: { Celsius: (temp: number) => temp - 273.15, Fahrenheit: (temp: number) => ((temp - 273.15) * 9 / 5) + 32 },
  };

  const converter = conversionTable[fromUnit]?.[toUnit];
  if (!converter) {
    throw new Error('Unsupported conversion');
  }

  const convertedTemperature = converter(temperature);

  return { convertedTemperature };
}
